14	const (
15		tokenMinDistance = 20.0 // CIE76 delta E: told apart at a glance
16		tokenMinContrast = 3.0  // WCAG non-text contrast
17	)
18	
19	var tokenKeys = []string{"token_input", "token_output", "token_cache_write", "token_cache_read"}
20	
21	// partialTheme returns the default theme with the given token keys replaced and
22	// every other token key removed, as a user-written theme file would be.
23	func partialTheme(t *testing.T, name string, set map[string]string) *Theme {
24		t.Helper()
25		raw, err := json.Marshal(DefaultTheme())
26		if err != nil {
27			t.Fatal(err)
28		}
29		m := map[string]any{}
30		if err := json.Unmarshal(raw, &m); err != nil {
31			t.Fatal(err)
32		}
33		for _, k := range tokenKeys {
34			delete(m, k)
35		}
36		for k, v := range set {
37			m[k] = v
38		}
39		raw, _ = json.Marshal(m)
40		th := &Theme{}
41		if err := json.Unmarshal(raw, th); err != nil {
42			t.Fatal(err)
43		}
44		th.Name = name
45		return th
46	}
47	
48	// requireTokenRoles fails unless TokenRoles() is exactly the four expected
49	// roles, so a loop over them can never pass vacuously.
50	func requireTokenRoles(t *testing.T) []TokenRole {
51		t.Helper()
52		want := []TokenRole{TokenRoleInput, TokenRoleOutput, TokenRoleCacheWrite, TokenRoleCacheRead}
53		roles := TokenRoles()
54		if len(roles) != len(want) {
55			t.Fatalf("TokenRoles() = %v, want %v", roles, want)
56		}
57		for i := range want {
58			if roles[i] != want[i] {
59				t.Fatalf("TokenRoles() = %v, want %v", roles, want)
60			}
61		}
62		return roles
63	}
64	
65	func tokenColors(t *testing.T) map[TokenRole]lipgloss.Color {
66		t.Helper()
67		roles := requireTokenRoles(t)
68		out := map[TokenRole]lipgloss.Color{}
69		for _, r := range roles {
70			out[r] = TokenColor(r)
71		}
72		return out
73	}
74	
75	func TestTokenRolesAreInBarOrder(t *testing.T) {
76		want := []TokenRole{TokenRoleInput, TokenRoleOutput, TokenRoleCacheWrite, TokenRoleCacheRead}
77		got := TokenRoles()
78		if len(got) != len(want) {
79			t.Fatalf("TokenRoles() = %v, want %v", got, want)
80		}
81		for i := range want {
82			if got[i] != want[i] {
83				t.Errorf("TokenRoles()[%d] = %q, want %q", i, got[i], want[i])
84			}
85		}
86	}
87	
88	func TestTokenColorsAreDistinct(t *testing.T) {
89		eachShippedTheme(t, func(t *testing.T, name string) {
90			roles := requireTokenRoles(t)
91			for i := range roles {
92				for j := i + 1; j < len(roles); j++ {
93					a, b := TokenColor(roles[i]), TokenColor(roles[j])
94					d, err := ColorDistance(a, b)
95					if err != nil {
96						t.Fatalf("theme %s: %s %q vs %s %q: %v", name, roles[i], a, roles[j], b, err)
97					}
98					if d < tokenMinDistance {
99						t.Errorf("theme %s: %s %s and %s %s are %.1f apart, want >= %.0f",
100							name, roles[i], a, roles[j], b, d, tokenMinDistance)
101					}
102				}
103			}
104		})
105	}
106	
107	func TestTokenColorsContrastWithBackground(t *testing.T) {
108		eachShippedTheme(t, func(t *testing.T, name string) {
109			for role, c := range tokenColors(t) {
110				for _, bg := range []struct {
111					what string
112					c    lipgloss.Color
113				}{{"background", ColorBackground}, {"selected row", ColorTableLineSelected}} {
114					r, err := ContrastRatio(c, bg.c)
115					if err != nil {
116						t.Fatalf("theme %s: %s %q on %s %q: %v", name, role, c, bg.what, bg.c, err)
117					}
118					if r < tokenMinContrast {
119						t.Errorf("theme %s: %s %s on %s %s is %.2f:1, want >= %.1f:1",
120							name, role, c, bg.what, bg.c, r, tokenMinContrast)
121					}
122				}
123			}
124		})
125	}
126	
127	func TestTokenColorsAreNotSeverityOrGaugeColours(t *testing.T) {
128		eachShippedTheme(t, func(t *testing.T, name string) {
129			others := map[string]lipgloss.Color{
130				"severity critical": ColorSeverityCritical,
131				"severity high":     ColorSeverityHigh,
132				"severity medium":   ColorSeverityMedium,
133				"severity low":      ColorSeverityLow,
134				"severity info":     ColorSeverityInfo,
135				"gauge fill (OK)":   ColorOK,
136				"dim":               ColorDim,
137				"gauge track":       GaugeTrackStyle().GetForeground().(lipgloss.Color),
138			}
139			for role, c := range tokenColors(t) {
140				for what, o := range others {
141					d, err := ColorDistance(c, o)
142					if err != nil {
143						t.Fatalf("theme %s: %s %q vs %s %q: %v", name, role, c, what, o, err)
144					}
145					if d < tokenMinDistance {
146						t.Errorf("theme %s: %s %s is %.1f from %s %s, want >= %.0f",
147							name, role, c, d, what, o, tokenMinDistance)
148					}
149				}
150			}
151		})
152	}
