154	func TestEveryShippedThemeSetsTheTokenKeys(t *testing.T) {
155		files, err := filepath.Glob("../../../themes/*.json")
156		if err != nil || len(files) == 0 {
157			t.Fatalf("no theme found under themes/*.json (err %v)", err)
