171					t.Errorf("%s: key %q missing or not a hex colour (%q)", filepath.Base(f), k, v)
172				}
173			}
174		}
175		th := DefaultTheme()
176		raw, _ := json.Marshal(th)
177		m := map[string]any{}
178		_ = json.Unmarshal(raw, &m)
179		for _, k := range tokenKeys {
180			if v, _ := m[k].(string); !strings.HasPrefix(v, "#") {
181				t.Errorf("DefaultTheme(): key %q missing or not a hex colour (%q)", k, v)
182			}
183		}
184	}
