211	func TestTokenColorFollowsAThemeChange(t *testing.T) {
212		withTheme(t, partialTheme(t, "a", map[string]string{"token_input": "#111111"}))
213		if got := TokenColor(TokenRoleInput); got != "#111111" {
214			t.Fatalf("TokenColor(input) = %q, want #111111", got)
215		}
216		ApplyTheme(partialTheme(t, "b", map[string]string{"token_input": "#222222"}))
217		if got := TokenColor(TokenRoleInput); got != "#222222" {
218			t.Errorf("TokenColor(input) = %q after a theme change, want #222222", got)
219		}
