231		for _, r := range requireTokenRoles(t) {
232			s := TokenStyle(r)
233			if got := s.GetForeground(); got != TokenColor(r) {
234				t.Errorf("TokenStyle(%s) foreground = %v, want %q", r, got, TokenColor(r))
235			}
236			if _, noBg := s.GetBackground().(lipgloss.NoColor); !noBg {
237				t.Errorf("TokenStyle(%s) sets a background %v; datatable supplies it (Rule 122)", r, s.GetBackground())
238			}
239		}
240		if got := TokenStyle("bogus").GetForeground(); got != ColorText {
241			t.Errorf("TokenStyle(unknown) foreground = %v, want ColorText", got)
242		}
243	}
244	
245	func TestColorDistance(t *testing.T) {
246		d, err := ColorDistance("#000000", "#ffffff")
247		if err != nil || math.Abs(d-100) > 0.5 {
248			t.Errorf("black/white = %.2f, %v; want ~100", d, err)
249		}
250		if d, err := ColorDistance("#89b4fa", "#89b4fa"); err != nil || d != 0 {
251			t.Errorf("identical = %v, %v; want 0", d, err)
252		}
253		ab, _ := ColorDistance("#89b4fa", "#f9e2af")
254		ba, _ := ColorDistance("#f9e2af", "#89b4fa")
255		if ab == 0 || math.Abs(ab-ba) > 1e-9 {
256			t.Errorf("not symmetric or zero: %v vs %v", ab, ba)
257		}
258		if d, _ := ColorDistance("#abc", "#aabbcc"); d != 0 {
259			t.Errorf("#abc vs #aabbcc = %v, want 0 (same as ContrastRatio's short form)", d)
260		}
261		for _, bad := range []lipgloss.Color{"red", "", "#12345", "#gggggg", "5"} {
