268	// Rule 119: the token roles bring no hex of their own; hex lives in colors.go
269	// (palette) and manager.go/theme files.
270	func TestTokenColorsFileHasNoHardcodedHex(t *testing.T) {
271		data, err := os.ReadFile("tokencolors.go")
272		if err != nil {
273			t.Fatal(err)
274		}
275		if strings.Contains(string(data), `lipgloss.Color("#`) {
276			t.Error(`tokencolors.go contains lipgloss.Color("#...") (Rule 119)`)
277		}
278	}
