package theme

import "github.com/charmbracelet/lipgloss"

// All color variables are populated by ApplyTheme(DefaultTheme()) in init().
// DefaultTheme() in manager.go is the single source of truth for hex values.

// Status colors
var (
	ColorOK    lipgloss.Color
	ColorError lipgloss.Color
	ColorWarn  lipgloss.Color
)

// UI colors (populated by ApplyTheme from DefaultTheme)
var (
	ColorPrimary    lipgloss.Color
	ColorSecondary  lipgloss.Color
	ColorBorder     lipgloss.Color
	ColorText       lipgloss.Color
	ColorDim        lipgloss.Color
	ColorHighlight  lipgloss.Color
	ColorWhite      lipgloss.Color
	ColorBlack      lipgloss.Color
	ColorBackground lipgloss.Color
)

// Component-specific colors (populated by ApplyTheme, fallback to semantic colors)
var (
	ColorTitleFg    lipgloss.Color
	ColorAppTitleFg lipgloss.Color
	ColorSubTitleFg lipgloss.Color

	ColorButtonFg         lipgloss.Color
	ColorButtonBg         lipgloss.Color
	ColorButtonInactiveFg lipgloss.Color
	ColorButtonInactiveBg lipgloss.Color

	ColorTabActiveFg   lipgloss.Color
	ColorTabActiveBg   lipgloss.Color
	ColorTabInactiveFg lipgloss.Color
	ColorTabInactiveBg lipgloss.Color

	ColorTableHeaderFg lipgloss.Color

	// ColorTableLineSelected is the background a datatable's plain "normal"
	// selected row paints per cell (§3.72) — DefaultTableStyles' s.Selected,
	// and render.go's cellStyle/runStyle selected branches (preserveColumnColors).
	// It used to alias ColorSeverityLow directly; a dedicated key lets a theme
	// tune the selection independently of the severity palette, which is what
	// SeverityLow now is — see its own doc below.
	ColorTableLineSelected lipgloss.Color

	ColorCmdLineFg         lipgloss.Color
	ColorCmdLineBg         lipgloss.Color
	ColorCmdLineInactiveFg lipgloss.Color

	ColorViewportBorder lipgloss.Color

	// ColorChartBg is the surface a chart is drawn on: one shade lighter than
	// third grey declares it here without touching a single caller.
	ColorShortcutDisabled lipgloss.Color

	// ColorPaletteBorder is the border and prompt glyph of the command palette
	// overlay. A closed alias of ColorPrimary assigned in ApplyTheme: no theme
	// file gains a key, so a user theme cannot break the 3:1 border contrast
	// unseen.
	ColorPaletteBorder lipgloss.Color

	// Icon colours, one per role rather than one per glyph (iconcolors.go).
	//
	// A glyph is a value, not a name: a table keyed on U+F0849 says nothing about
	// what it is for, and the next reader cannot tell a wrong entry from a right
	// one. A role can be argued about, which is the whole point of a palette.
	//
	// They follow the severity block's shape rather than the syntax block's: a
	// theme file may override each of them, because these are the one part of the
	// palette a user is likely to have an opinion about — an icon is the first
	// thing seen on a row.
	ColorIconNamespace   lipgloss.Color
	ColorIconRepository  lipgloss.Color
	ColorIconVisPublic   lipgloss.Color
	ColorIconVisInternal lipgloss.Color
	ColorIconVisPrivate  lipgloss.Color
	ColorIconDirectory   lipgloss.Color
	ColorIconFile        lipgloss.Color
	ColorIconImage       lipgloss.Color

	// Severity colors (background + foreground pairs)
	//
	// ColorSeverityLow's default now equals ColorDim's — the tone the :sec
	// inventory already uses for a "0" count (inventory_table.go, countColumn):
	// a LOW finding is, by the same reasoning that grades a count column,
	// barely worth a glance next to CRITICAL/HIGH/MEDIUM. A theme may still
	// separate the two; the default treats "low severity" and "nothing found"
	// as the same shade of unremarkable.
	SeverityCritical   string `json:"severity_critical,omitempty"`
	SeverityCriticalFg string `json:"severity_critical_fg,omitempty"`
	SeverityHigh       string `json:"severity_high,omitempty"`
	SeverityHighFg     string `json:"severity_high_fg,omitempty"`
	SeverityMedium     string `json:"severity_medium,omitempty"`
	SeverityMediumFg   string `json:"severity_medium_fg,omitempty"`
	SeverityLow        string `json:"severity_low,omitempty"`
	SeverityLowFg      string `json:"severity_low_fg,omitempty"`
	SeverityInfo       string `json:"severity_info,omitempty"`
	SeverityInfoFg     string `json:"severity_info_fg,omitempty"`

	// Icon colours (optional, fall back to the semantic palette)
	IconNamespace   string `json:"icon_namespace,omitempty"`
	IconRepository  string `json:"icon_repository,omitempty"`
	IconVisPublic   string `json:"icon_vis_public,omitempty"`
	IconVisInternal string `json:"icon_vis_internal,omitempty"`
	IconVisPrivate  string `json:"icon_vis_private,omitempty"`
	IconDirectory   string `json:"icon_directory,omitempty"`
	IconFile        string `json:"icon_file,omitempty"`
	IconImage       string `json:"icon_image,omitempty"`
}

// DefaultTheme returns the default theme (Catppuccin Mocha)
func DefaultTheme() *Theme {
	return &Theme{
		Name:             "default",
	ColorFooterInfo = ColorText
	ColorFooterWarn = ColorSeverityMedium
	ColorFooterError = ColorSeverityCritical

	// The image update arrow (§3.88), in the structural colour: news, not a
	// finding.
	ColorUpdateAvailable = ColorSecondary

	// Icon colours (iconcolors.go). Assigned here like every other alias, and
	// through applyColor so a theme file can name its own.
	//
	// The defaults carry an argument each. A namespace takes the structural
	// colour the headers and tabs already use, and a repository the leaf colour
	// beside it. Public is green because it is the state worth spotting without
	// reading; internal is the warning hue because it is restricted without being
	// closed; and private is **dim** because it is the majority — a colour every
	// row carries informs of nothing (Rule 122), which is the same argument the
	// severity counters make for their zeroes.
	ColorIconNamespace = applyColor(t.IconNamespace, ColorSecondary)
	ColorIconRepository = applyColor(t.IconRepository, ColorPrimary)
	ColorIconVisPublic = applyColor(t.IconVisPublic, ColorOK)
	ColorIconVisInternal = applyColor(t.IconVisInternal, ColorWarn)
	ColorIconVisPrivate = applyColor(t.IconVisPrivate, ColorDim)

	// The workspaces and :sec listings. A directory takes the namespace's
	// colour and the argument is the same shape: both are the thing that
	// *holds* repositories, on a forge and on a disk. They are two roles rather
	// than one alias so a theme can separate them; the default says they are
	// the same idea.
	ColorIconDirectory = applyColor(t.IconDirectory, ColorSecondary)

	// A loose file in a workspaces listing is the row nothing applies to — W, S
	// and F are all greyed for it (Rule 130, availability.go). Dim is what the
	// shortcut column already says about that row, said once more.
	ColorIconFile = applyColor(t.IconFile, ColorDim)

	// An image takes the highlight rather than a third purple: Primary and
	// Secondary are a mauve and a lavender one notch apart, and the :sec
	// inventory's first column has exactly two values — the one place where the
	// two would sit on adjacent rows with nothing else to separate them.
	ColorIconImage = applyColor(t.IconImage, ColorHighlight)

	// A disabled shortcut's key (Rule 130), same kind of alias.
	ColorShortcutDisabled = ColorDim
	ColorPaletteBorder = ColorPrimary

